def find_path(graph, start, goal):
    priority_queue = [(0, start)]
    costs = {node: float('infinity') for node in graph}
    costs[start] = 0
    previous = {node: None for node in graph}
    paths = {node: None for node in graph}
    while priority_queue:
        current_cost, current_node = heapq.heappop(priority_queue)
        if current_node == goal:
            path = []
            while current_node is not None:
                path.append(current_node)
                current_node = previous[current_node]
            return path[::-1]
        if current_node in paths:
            continue
        paths[current_node] = current_cost
        for neighbor, edge_cost in graph[current_node].items():
            if current_cost + edge_cost < costs[neighbor]:
                costs[neighbor] = current_cost + edge_cost
                previous[neighbor] = current_node
                heapq.heappush(priority_queue, (current_cost + edge_cost, neighbor))
    return None
