from heapq import heappop, heappush

def dijkstra(graph, start, goal):
    pipeline = [(0, start)]
    distances = {node: float('infinity') for node in graph}
    distances[start] = 0
    while pipeline:
        current_distance, current_node = heappop(pipeline)
        if current_node == goal:
            return reconstruct_path(graph, start, goal, distances)
        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heappush(pipeline, (distance, neighbor))
    return None

def reconstruct_path(graph, start, goal, distances):
    path = []
    current_node = goal
    while current_node != start:
        path.append(current_node)
        for node, weight in graph[current_node]:
            if distances[node] + weight == distances[current_node]:
                current_node = node
                break
        else:
            return None
    path.append(start)
    path.reverse()
    return path

def find_path(graph, start, goal):
    distances = dijkstra(graph, start, goal)
    if distances is None:
        return None
    return reconstruct_path(graph, start, goal, distances)
